/*
 * phdate.c - R11F: direct probe of Phoon's date_parse (third_party/phoon, patched).
 * Each argument is parsed; the result is printed as the time_t value, or "refused"
 * when date_parse returns (time_t) -1.  The expected values are generated by
 * gen_expected.py from Python's calendar.timegm, not from this program.
 * Built with the Phoon source (date_parse.c, with -DOS_SYSV); see scripts/r11f-volume.sh.
 */
#include <stdio.h>
#include <time.h>

time_t date_parse( char *str );

int main( int argc, char **argv )
{
	int i;
	time_t t;

	for ( i = 1; i < argc; i++ )
	{
		t = date_parse( argv[i] );
		if ( t == (time_t) -1 )
			printf( "PHDATE %s -> refused\n", argv[i] );
		else
			printf( "PHDATE %s -> %lu\n", argv[i], (unsigned long) t );
	}
	printf( "QDOS/386 R11F PHDATE DONE\n" );
	return 0;
}
